// One item per changed file that arrived with content (base64).
// Files over 1 MB arrive as metadata only (contentOmitted) and are skipped here.
const body = $input.first().json.body ?? $input.first().json;
const stamp = new Date(body.generatedAt ?? Date.now()).toISOString().slice(0, 10);
const out = [];
for (const f of body.files ?? []) {
  if (!f.content) continue;
  const safe = `${f.root}__${String(f.path).replace(/[\\/]+/g, '__')}`;
  out.push({
    json: { root: f.root, path: f.path, size: f.size, modified: f.modified, host: body.host, day: stamp },
    binary: { data: { data: f.content, mimeType: 'application/octet-stream', fileName: safe } },
  });
}
return out;
